// `IPC_COMMANDS` is generated by `pnpm contracts:generate` from the command list in crates/ide-ipc.
include!("ipc_commands.rs");

fn main() {
    println!("cargo:rerun-if-changed=ipc_commands.rs");
    println!("cargo:rerun-if-changed=permissions");
    // Gives every app command an `allow-<command>` permission, so a window can
    // call only the commands its capability grants (capabilities/main.json).
    let manifest = tauri_build::AppManifest::new().commands(IPC_COMMANDS);
    if let Err(error) =
        tauri_build::try_build(tauri_build::Attributes::new().app_manifest(manifest))
    {
        panic!("tauri build step failed: {error:#}");
    }
}
